function tr(key){return (T[state.lang]&&T[state.lang][key])||T.ru[key]||key;}
function applyLanguage(lang){if(!T[lang])return;state.lang=lang;document.documentElement.lang=lang==="uzc"?"uz-Cyrl":lang==="uz"?"uz-Latn":lang;
document.querySelectorAll("[data-i18n]").forEach(el=>{const k=el.dataset.i18n;if(T[lang][k]!==undefined)el.innerHTML=T[lang][k];});
document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>{const k=el.dataset.i18nPlaceholder;if(T[lang][k]!==undefined)el.placeholder=T[lang][k];});
$("#currentLanguage").textContent=({ru:"RU",uz:"UZ",uzc:"ЎЗ",en:"EN"})[lang];
document.querySelectorAll(".language-option").forEach(b=>b.classList.toggle("active",b.dataset.lang===lang));
render();renderRegionOptions();if(state.map)updateRegionStyles();
}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),3000);}
function dateLabel(value){const d=new Date(value+"T12:00:00");return Number.isNaN(d.getTime())?"":d.toLocaleDateString(state.lang==="uz"?"uz-UZ":state.lang==="uzc"?"uz-Cyrl-UZ":state.lang==="en"?"en-GB":"ru-RU",{day:"numeric",month:"short"});}
const categoryKey={"Электроника":"electronics","Аксессуары":"accessories","Ключи":"keys","Сумки":"bags","Документы":"documents","Одежда":"clothing","Другое":"other"};
function card(x){const found=x.kind==="Найдено",symbols={"Электроника":"phone","Аксессуары":"wallet","Ключи":"key","Сумки":"backpack","Документы":"file-text","Одежда":"shirt","Другое":"package"},symbol=x.icon||symbols[x.category]||"package";return '<article class="listing-card" data-listing-id="'+safe(x.id)+'"><div class="card-art '+(found?"found-art":"lost-art")+'">'+(x.photoUrl?'<img class="listing-photo" src="'+safe(x.photoUrl)+'" alt="" loading="lazy" decoding="async">':'')+'<span class="card-kind '+(found?"kind-found":"kind-lost")+'">'+tr(found?"kindFound":"kindLost")+'</span><span class="item-symbol">'+icon(symbol)+'</span><span class="art-orbit"></span></div><div class="card-content"><div class="card-meta"><span>'+safe(tr(categoryKey[x.category]||"other"))+'</span><span>'+safe(dateLabel(x.date))+'</span></div><h3>'+safe(x.title)+'</h3><p class="card-place">'+icon("map-pin")+safe(x.area)+'</p><p class="card-description">'+safe(x.description)+'</p><div class="card-bottom"><span>'+icon("shield")+tr("demoApproved")+'</span><button class="card-qr-btn" type="button" data-qr-id="'+safe(x.id)+'" aria-label="QR-код объявления"><svg><use href="/icons.svg#qr-code"/></svg> QR-код</button></div></div></article>';}
function render(){if(!$("#listingGrid"))return;const list=state.items.filter(x=>(state.kind==="Все"||x.kind===state.kind)&&(state.category==="Все категории"||x.category===state.category)&&(!state.query||[x.title,x.category,x.area,x.description].join(" ").toLowerCase().includes(state.query)));$("#listingGrid").innerHTML=list.map(card).join("");$("#listingGrid").classList.toggle("hidden",!list.length);$("#emptyState").classList.toggle("hidden",!!list.length);$("#resultCount").textContent=tr("shownCount").replace("{shown}",list.length).replace("{total}",state.items.length);updateMapMarkers();animateListingCards();}

function animateListingCards(){
 const cards=[...document.querySelectorAll(".listing-card:not([data-motion-ready])")];
 if(!cards.length)return;cards.forEach(card=>card.dataset.motionReady="1");
 if(!window.gsap||window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;
 if(window.ScrollTrigger){gsap.fromTo(cards,{y:10,opacity:0},{y:0,opacity:1,duration:.28,stagger:.025,ease:"power2.out",scrollTrigger:{trigger:"#listingGrid",start:"top 96%"}});}
 else gsap.fromTo(cards,{y:8,opacity:0},{y:0,opacity:1,duration:.24,stagger:.02,ease:"power2.out"});
 
}

async function load(){try{const r=await fetch("/api/listings");if(!r.ok)throw Error();const d=await r.json();state.items=d.items||[];render();}catch{$("#listingGrid").innerHTML='<div class="loading">'+tr("loadingError")+'</div>';$("#resultCount").textContent="";}}
function openForm(kind){$("#listingKind").value=kind;$("#modalTitle").textContent=tr(kind==="Потеряно"?"lostBtn":"foundBtn");$("#modalBackdrop").classList.remove("hidden");document.body.classList.add("modal-open");$("#itemDate").value=new Date().toISOString().slice(0,10);setTimeout(()=>$("#itemTitle").focus(),80);}
function closeForm(){$("#modalBackdrop").classList.add("hidden");document.body.classList.remove("modal-open");}
document.addEventListener("click",e=>{const b=e.target.closest("[data-open-form]");if(b)openForm(b.dataset.openForm);});
$("#closeModal").addEventListener("click",closeForm);$("#modalBackdrop").addEventListener("click",e=>{if(e.target===$("#modalBackdrop"))closeForm();});
document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeForm();$("#languagePanel").classList.add("hidden");$("#languageTrigger").setAttribute("aria-expanded","false");}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();$("#searchInput").focus();}});
$("#listingForm").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,button=$("#submitBtn"),error=$("#formError");error.textContent="";button.disabled=true;button.textContent=tr("submitReview")+"…";const data=new FormData(form);try{const r=await fetch("/api/listings",{method:"POST",body:data});const result=await r.json();if(!r.ok)throw Error(result.error||tr("loadingError"));form.reset();closeForm();toast(result.message||tr("formSent"));}catch(err){error.textContent=err.message;}finally{button.disabled=false;button.textContent=tr("submitReview");}});
$("#searchInput").addEventListener("input",e=>{state.query=e.target.value.trim().toLowerCase();render();});
$("#searchBtn").addEventListener("click",render);$("#categoryFilter").addEventListener("change",e=>{state.category=e.target.value;render();});
$("#kindFilters").addEventListener("click",e=>{const b=e.target.closest("[data-kind]");if(!b)return;state.kind=b.dataset.kind;document.querySelectorAll(".chip").forEach(x=>x.classList.toggle("active",x===b));render();});
function reset(){state.kind="Все";state.category="Все категории";state.query="";$("#searchInput").value="";$("#categoryFilter").value="Все категории";document.querySelectorAll(".chip").forEach(x=>x.classList.toggle("active",x.dataset.kind==="Все"));render();}
$("#clearFilters").addEventListener("click",reset);$("#emptyReset").addEventListener("click",reset);$("#partnerBtn").addEventListener("click",()=>toast(tr("partnerSoon")));
$("#languageTrigger").addEventListener("click",()=>{const p=$("#languagePanel"),open=p.classList.toggle("hidden")===false;$("#languageTrigger").setAttribute("aria-expanded",String(open));});
$("#languagePanel").addEventListener("click",e=>{const b=e.target.closest("[data-lang]");if(!b)return;applyLanguage(b.dataset.lang);$("#languagePanel").classList.add("hidden");$("#languageTrigger").setAttribute("aria-expanded","false");});
document.addEventListener("click",e=>{if(!e.target.closest(".language-wrap")){$("#languagePanel").classList.add("hidden");$("#languageTrigger").setAttribute("aria-expanded","false");}});
function regionLabel(p){const i=regionNames.findIndex(r=>r.en===p.ADM1_EN);return i>=0?regionNames[i][state.lang]:(p.ADM1_RU||p.ADM1_EN||tr("unknownRegion"));}
function renderRegionOptions(){const sel=$("#regionSelect");if(!sel)return;const keep=sel.value;sel.innerHTML='<option value="">'+tr("allUzbekistan")+'</option>'+state.regions.map((f,i)=>'<option value="'+i+'">'+safe(regionLabel(f.properties))+'</option>').join("");if(keep)sel.value=keep;}
function updateRegionStyles(){if(!state.regionLayer)return;state.regionLayer.eachLayer(layer=>{const selected=$("#regionSelect").value!==""&&Number($("#regionSelect").value)===state.regions.indexOf(layer.feature);layer.setStyle({color:selected?"#242a31":"#a7b0a9",weight:selected?2.5:1.05,fillColor:selected?"#a8c9b3":"#dfe9e2",fillOpacity:selected?.58:.38});});}
function focusRegion(index){if(!state.map)return;if(index===""||index===null){state.map.fitBounds(state.regionLayer.getBounds(),{padding:[18,18]});$("#regionSelect").value="";updateRegionStyles();return;}const layer=state.regionLayer.getLayers()[Number(index)];if(layer){state.map.fitBounds(layer.getBounds(),{padding:[25,25],maxZoom:8});$("#regionSelect").value=String(index);updateRegionStyles();const name=regionLabel(layer.feature.properties);toast(tr("mapSelected")+name);}}
async function initMap(){if(!window.L){$("#mapOverlay").innerHTML=tr("mapError");return;}try{state.map=L.map("uzbekistanMap",{zoomControl:true,scrollWheelZoom:false,minZoom:5,maxBoundsViscosity:1}).setView([41.2,64.6],5);/* Uzbekistan-only vector map: no surrounding-country basemap tiles */const response=await fetch("/uzbekistan-regions.geojson");if(!response.ok)throw Error("geojson");const data=await response.json();state.regions=(data.features||[]).map(feature=>({...feature,geometry:{type:"MultiPolygon",coordinates:geometryPolygons(feature.geometry)}}));const renderData={type:"FeatureCollection",features:state.regions};state.regionLayer=L.geoJSON(renderData,{style:()=>({color:"#60796a",weight:2,opacity:.95,fillColor:"#d5e5d9",fillOpacity:1}),onEachFeature:(feature,layer)=>{const name=regionLabel(feature.properties);layer.bindTooltip(name,{permanent:true,direction:"center",className:"region-name-label",opacity:.92});layer.on({mouseover:e=>e.target.setStyle({weight:2,color:"#6c8f78",fillOpacity:.6}),mouseout:()=>updateRegionStyles(),click:()=>{const i=state.regions.indexOf(feature);focusRegion(i);}});}}).addTo(state.map);state.mapMarkers=window.L.markerClusterGroup?L.markerClusterGroup({showCoverageOnHover:false,spiderfyOnMaxZoom:true,zoomToBoundsOnClick:true,maxClusterRadius:55,chunkedLoading:true}):L.layerGroup();state.map.addLayer(state.mapMarkers);const uzBounds=state.regionLayer.getBounds();state.map.fitBounds(uzBounds,{padding:[18,18]});state.map.setMaxBounds(uzBounds.pad(0.04));state.map.setMinZoom(Math.max(5,state.map.getZoom()));renderRegionOptions();updateMapMarkers();$("#mapOverlay").classList.add("done");setTimeout(()=>{$("#mapOverlay").classList.add("hidden");state.map.invalidateSize();},350);}catch(error){console.error("map_init_failed",error);$("#mapOverlay").innerHTML=tr("mapError");}}
function normalizedText(value){return String(value||"").toLocaleLowerCase().replace(/[ёъьʻ’'"]/g,"").replace(/[^a-zа-яўқғҳ0-9]+/g," ").trim();}
function regionForListing(area){const needle=normalizedText(area);if(!needle)return null;return state.regions.find(feature=>{const p=feature.properties||{};const index=regionNames.findIndex(r=>r.en===p.ADM1_EN);const names=[p.ADM1_EN,p.ADM1_RU,p.ADM1_UZ,...(index>=0?[regionNames[index].ru,regionNames[index].uz,regionNames[index].uzc,regionNames[index].en]:[])].filter(Boolean);return names.some(name=>{const n=normalizedText(name);return n.length>3&&(needle.includes(n)||n.includes(needle));});})||null;}
function regionCenter(feature){if(!feature||!state.regionLayer)return null;const layer=state.regionLayer.getLayers().find(x=>x.feature===feature);if(!layer)return null;const c=layer.getBounds().getCenter();return [c.lat,c.lng];}
function markerPopup(item){const wrap=document.createElement("div");wrap.className="map-listing-popup";const badge=document.createElement("strong");badge.className=item.kind==="Найдено"?"popup-kind popup-found":"popup-kind popup-lost";badge.textContent=tr(item.kind==="Найдено"?"kindFound":"kindLost");wrap.appendChild(badge);if(item.photoUrl){const img=document.createElement("img");img.src=item.photoUrl;img.alt="Фото объявления";img.loading="lazy";wrap.appendChild(img);}const title=document.createElement("h3");title.textContent=item.title||"Объявление";wrap.appendChild(title);const place=document.createElement("p");place.textContent=(item.area||"Узбекистан")+" · "+(item.category||"");wrap.appendChild(place);const desc=document.createElement("p");desc.textContent=item.description||"";wrap.appendChild(desc);const date=document.createElement("small");date.textContent=dateLabel(item.date);wrap.appendChild(date);return wrap;}
function updateMapMarkers(){if(!state.mapMarkers||!state.regions.length)return;state.mapMarkers.clearLayers();const filtered=state.items.filter(item=>state.mapKind==="Все"||item.kind===state.mapKind);const markers=[];filtered.forEach(item=>{const feature=regionForListing(item.area);const center=regionCenter(feature);if(!center)return;const found=item.kind==="Найдено";const marker=L.marker(center,{icon:L.divIcon({className:"topdim-map-marker-wrap",html:'<span class="topdim-map-marker '+(found?"marker-found":"marker-lost")+'"><span></span></span>',iconSize:[26,34],iconAnchor:[13,30]})});marker.bindPopup(markerPopup(item),{maxWidth:245,minWidth:190});markers.push(marker);});if(typeof state.mapMarkers.addLayers==="function"){state.mapMarkers.addLayers(markers);}else{markers.forEach(marker=>state.mapMarkers.addLayer(marker));}}
$("#mapKindFilters")?.addEventListener("click",e=>{const button=e.target.closest("[data-map-kind]");if(!button)return;state.mapKind=button.dataset.mapKind;$("#mapKindFilters").querySelectorAll("[data-map-kind]").forEach(x=>x.classList.toggle("active",x===button));updateMapMarkers();});
$("#regionSelect").addEventListener("change",e=>focusRegion(e.target.value));
$("#mapReset").addEventListener("click",()=>focusRegion(""));
$("#regionSearch").addEventListener("input",e=>{const q=e.target.value.trim().toLowerCase();if(!q){$("#regionSelect").value="";updateRegionStyles();return;}const i=state.regions.findIndex(f=>{const p=f.properties;return [p.ADM1_EN,p.ADM1_RU,p.ADM1_UZ,regionLabel(p)].join(" ").toLowerCase().includes(q);});if(i>=0)focusRegion(i);});
function animate(){
 const reduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;
 const targets=document.querySelectorAll(".hero-copy,.hero-art,.trust-strip,.section,.org-section,.safety,footer");
 if("IntersectionObserver"in window){const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("is-visible");io.unobserve(entry.target);}}),{threshold:.04,rootMargin:"0px 0px 40px 0px"});targets.forEach(el=>{el.classList.add("reveal");io.observe(el);});}
 if(!window.gsap||reduced)return;
 if(window.ScrollTrigger)gsap.registerPlugin(window.ScrollTrigger);
 const intro=gsap.timeline({defaults:{ease:"power2.out"}});
 intro.from(".sidebar-brand",{x:-8,opacity:0,duration:.28})
  .from(".side-link",{x:-5,opacity:0,stagger:.02,duration:.18},"-=.14")
  .from(".topbar .top-actions > *",{y:-4,opacity:0,stagger:.03,duration:.18},"-=.1")
  .from(".hero-copy .eyebrow",{y:5,opacity:0,duration:.2},"-=.05")
  .from(".hero-copy h1",{y:12,opacity:0,duration:.34},"-=.1")
  .from(".hero-copy>p,.hero-buttons,.hero-note",{y:7,opacity:0,stagger:.03,duration:.2},"-=.16")
  .from(".hero-illustration",{y:10,rotate:-1,scale:.99,opacity:0,duration:.36},"-=.22");
 if(window.ScrollTrigger&&!matchMedia("(max-width:800px)").matches){
  gsap.utils.toArray(".section-heading,.steps article,.org-copy,.org-visual,.safety").forEach(el=>gsap.fromTo(el,{y:9,opacity:.7},{y:0,opacity:1,duration:.32,ease:"power2.out",scrollTrigger:{trigger:el,start:"top 96%",once:true}}));
 }
}

/* QR sharing and scanning */
let activeQrUrl="", scannerStream=null, scannerFrame=0, scannerDetector=null, scannerActive=false;
function listingUrl(id){const u=new URL("/",location.origin);u.searchParams.set("listing",id);return u.href;}
function showQr(id){
 const item=state.items.find(x=>String(x.id)===String(id));if(!item){toast("Объявление не найдено.");return;}
 if(!window.QRCode){toast("Генератор QR временно недоступен. Обнови страницу.");return;}
 activeQrUrl=listingUrl(item.id);$("#qrCanvas").innerHTML="";
 $("#qrTitle").textContent="QR-код: "+item.title;
 $("#qrDescription").textContent=(item.kind==="Найдено"?"Найдено":"Потеряно")+" · "+item.area;
 new QRCode($("#qrCanvas"),{text:activeQrUrl,width:224,height:224,colorDark:"#17251d",colorLight:"#ffffff",correctLevel:QRCode.CorrectLevel.H});
 openQrLayer("qrBackdrop");
}
function openQrLayer(id){const el=$("#"+id);el.classList.remove("hidden");el.setAttribute("aria-hidden","false");document.body.classList.add("qr-open");if(window.gsap&&!matchMedia("(prefers-reduced-motion: reduce)").matches)gsap.fromTo(el.querySelector(".qr-dialog"),{y:22,opacity:0,scale:.97},{y:0,opacity:1,scale:1,duration:.32,ease:"power3.out"});}
function closeQrLayer(id){const el=$("#"+id);if(!el)return;el.classList.add("hidden");el.setAttribute("aria-hidden","true");if(!document.querySelector(".qr-backdrop:not(.hidden)"))document.body.classList.remove("qr-open");}
document.addEventListener("click",e=>{const b=e.target.closest("[data-qr-id]");if(b){e.preventDefault();showQr(b.dataset.qrId);}});
document.querySelectorAll("[data-close-qr]").forEach(b=>b.addEventListener("click",()=>closeQrLayer("qrBackdrop")));
$("#qrBackdrop").addEventListener("click",e=>{if(e.target.id==="qrBackdrop")closeQrLayer("qrBackdrop");});
$("#downloadQr").addEventListener("click",()=>{const canvas=$("#qrCanvas canvas"),img=$("#qrCanvas img");const data=canvas?canvas.toDataURL("image/png"):img?.src;if(!data){toast("QR-код ещё создаётся.");return;}const a=document.createElement("a");a.href=data;a.download="topdim-qr.png";a.click();});
$("#shareQr").addEventListener("click",async()=>{if(!activeQrUrl)return;try{if(navigator.share)await navigator.share({title:"Объявление TopDim",url:activeQrUrl});else{await navigator.clipboard.writeText(activeQrUrl);toast("Ссылка скопирована.");}}catch(e){if(e.name!=="AbortError")toast("Не удалось поделиться ссылкой.");}});
async function openListingDetail(id){
 if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id))return;
 try{const r=await fetch("/api/listings/"+encodeURIComponent(id));const data=await r.json();if(!r.ok)throw Error(data.error||"Объявление не найдено.");const x=data.item;const root=$("#detailContent");root.innerHTML='<div class="qr-eyebrow">TOPDIM · '+(x.kind==="Найдено"?"НАЙДЕНО":"ПОТЕРЯНО")+'</div>'+(x.photoUrl?'<img class="detail-photo" src="'+safe(x.photoUrl)+'" alt="Фото вещи">':'')+'<h2 id="detailTitle">'+safe(x.title)+'</h2><div class="detail-meta">'+safe(x.category)+' · '+safe(dateLabel(x.date))+'</div><p class="detail-place">⌖ '+safe(x.area)+'</p><p class="detail-description">'+safe(x.description)+'</p><small class="qr-footnote">Объявление опубликовано после проверки. Не публикуйте личные данные и точный адрес.</small>';openQrLayer("detailBackdrop");history.replaceState(null,"",listingUrl(id));}
 catch(err){toast(err.message||"Не удалось открыть объявление.");}
}
document.querySelectorAll("[data-close-detail]").forEach(b=>b.addEventListener("click",()=>closeQrLayer("detailBackdrop")));
$("#detailBackdrop").addEventListener("click",e=>{if(e.target.id==="detailBackdrop")closeQrLayer("detailBackdrop");});
function stopQrScanner(){scannerActive=false;if(scannerFrame)cancelAnimationFrame(scannerFrame);scannerFrame=0;if(scannerStream){scannerStream.getTracks().forEach(t=>t.stop());scannerStream=null;}const v=$("#qrVideo");if(v)v.srcObject=null;closeQrLayer("scannerBackdrop");}
document.querySelectorAll("[data-close-scanner]").forEach(b=>b.addEventListener("click",stopQrScanner));
$("#stopScanner").addEventListener("click",stopQrScanner);
$("#openQrScanner").addEventListener("click",startQrScanner);
async function startQrScanner(){
 openQrLayer("scannerBackdrop");$("#scannerStatus").textContent="Запрашиваем доступ к камере…";
 if(!navigator.mediaDevices?.getUserMedia){$("#scannerStatus").textContent="Камера недоступна. Открой сайт через HTTPS и разреши доступ.";return;}
 try{
  scannerStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:"environment"}}});
  const video=$("#qrVideo");video.srcObject=scannerStream;await video.play();scannerActive=true;
  scannerDetector=("BarcodeDetector"in window)?new BarcodeDetector({formats:["qr_code"]}):null;
  $("#scannerStatus").textContent="Наведите камеру на QR-код.";
  const canvas=document.createElement("canvas"),ctx=canvas.getContext("2d",{willReadFrequently:true});
  const tick=async()=>{
   if(!scannerActive)return;
   if(video.readyState>=2){
    try{
     let value=null;
     if(scannerDetector){const codes=await scannerDetector.detect(video);if(codes.length)value=codes[0].rawValue;}
     else if(window.jsQR){canvas.width=video.videoWidth;canvas.height=video.videoHeight;ctx.drawImage(video,0,0,canvas.width,canvas.height);const frame=ctx.getImageData(0,0,canvas.width,canvas.height);const code=jsQR(frame.data,frame.width,frame.height,{inversionAttempts:"dontInvert"});if(code)value=code.data;}
     if(value){const u=new URL(value,location.origin);if(u.origin===location.origin&&u.pathname==="/"&&(u.searchParams.get("listing")||u.searchParams.get("tag"))){const listingId=u.searchParams.get("listing"),tagId=u.searchParams.get("tag");stopQrScanner();if(tagId)openPublicTag(tagId);else openListingDetail(listingId);return;}$("#scannerStatus").textContent="Этот QR-код не является ссылкой на TopDim. Используй QR объявления или QR-метки.";}
    }catch(e){console.debug("qr_scan_frame",e);}
   }
   scannerFrame=requestAnimationFrame(tick);
  };tick();
  if(!scannerDetector&&!window.jsQR)$("#scannerStatus").textContent="Сканер не поддерживается этим браузером. Обнови Chrome.";
 }catch(err){$("#scannerStatus").textContent=err.name==="NotAllowedError"?"Разреши доступ к камере в настройках браузера.":"Не удалось запустить камеру. Проверь, что она не занята другим приложением.";}
}
document.addEventListener("keydown",e=>{if(e.key==="Escape"){stopQrScanner();closeQrLayer("qrBackdrop");closeQrLayer("detailBackdrop");}});


/* Responsive sidebar navigation and active section tracking */
(()=>{
 const links=[...document.querySelectorAll("[data-section]")], sections=["home","catalog","mapSection","how","organizations"].map(id=>document.getElementById(id)).filter(Boolean);
 const setActive=id=>links.forEach(a=>a.classList.toggle("active",a.dataset.section===id));
 links.forEach(a=>a.addEventListener("click",()=>{setActive(a.dataset.section);document.getElementById("appSidebar")?.classList.remove("sidebar-open");}));
 if("IntersectionObserver"in window){const io=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(visible)setActive(visible.target.id);},{rootMargin:"-18% 0px -62% 0px",threshold:[0,.15,.35,.6]});sections.forEach(s=>io.observe(s));}
 const menu=$("#menuBtn");menu?.addEventListener("click",()=>{$("#appSidebar")?.classList.toggle("sidebar-open");});
 document.addEventListener("click",e=>{const side=$("#appSidebar");if(side?.classList.contains("sidebar-open")&&!e.target.closest("#appSidebar")&&!e.target.closest("#menuBtn"))side.classList.remove("sidebar-open");});
})();

applyLanguage("ru");load().then(()=>{const id=new URLSearchParams(location.search).get("listing");if(id)openListingDetail(id);});initMap();animate();
const photoField=$("#itemPhoto");photoField?.addEventListener("change",()=>{const f=photoField.files?.[0];if(!f)return;if(!["image/jpeg","image/png","image/webp"].includes(f.type)||f.size>5*1024*1024){photoField.value="";toast("Фото должно быть JPG, PNG или WebP до 5 МБ.");return;}const im=$("#photoPreview");im.src=URL.createObjectURL(f);im.classList.remove("hidden");});
function pointInRing(lon,lat,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=ring[i][0],yi=ring[i][1],xj=ring[j][0],yj=ring[j][1];const crosses=((yi>lat)!==(yj>lat))&&(lon<(xj-xi)*(lat-yi)/(yj-yi+Number.EPSILON)+xi);if(crosses)inside=!inside;}return inside;}
function pointInPolygon(lon,lat,poly){if(!poly?.length||!pointInRing(lon,lat,poly[0]))return false;for(let i=1;i<poly.length;i++)if(pointInRing(lon,lat,poly[i]))return false;return true;}
function geometryPolygons(geometry){if(!geometry)return[];if(geometry.type==="Polygon")return[geometry.coordinates];if(geometry.type==="MultiPolygon")return geometry.coordinates;if(geometry.type==="GeometryCollection")return(geometry.geometries||[]).flatMap(geometryPolygons);return[];}
function findRegionAt(lat,lon){for(const feature of state.regions){const polys=geometryPolygons(feature.geometry);if(polys.some(poly=>pointInPolygon(lon,lat,poly)))return regionLabel(feature.properties);}return null;}
function askLocationForForm(){const s=$("#locationStatus"),area=document.querySelector('#listingForm [name="area"]');if(!navigator.geolocation){s.textContent="Геолокация недоступна. Введи примерную область вручную.";return;}s.textContent="Ожидаем разрешение браузера…";navigator.geolocation.getCurrentPosition(p=>{const region=findRegionAt(p.coords.latitude,p.coords.longitude);if(region){area.value=region;s.textContent="Определена область: "+region+". Проверь значение. Точные координаты не отправлялись и не сохраняются.";}else{s.textContent="Не удалось определить область. Введи её вручную.";}},()=>{s.textContent="Доступ к местоположению не предоставлен. Можно указать область вручную.";},{enableHighAccuracy:false,timeout:12000,maximumAge:60000});}
function askLocation(){if(!navigator.geolocation){toast("Геолокация недоступна в браузере.");return;}navigator.geolocation.getCurrentPosition(p=>{const detectedRegion=findRegionAt(p.coords.latitude,p.coords.longitude);const feature=state.regions.find(f=>regionLabel(f.properties)===detectedRegion);const ll=regionCenter(feature);if(!ll){toast("Не удалось определить область Узбекистана.");return;}const name=regionLabel(feature.properties);if(state.userMarker)state.userMarker.setLatLng(ll);else state.userMarker=L.circleMarker(ll,{radius:10,color:"#fff",weight:3,fillColor:"#293b63",fillOpacity:1}).addTo(state.map);state.userMarker.bindPopup("Примерное местоположение: "+safe(name));state.map.setView(ll,6,{animate:false});state.userMarker.openPopup();},()=>toast("Доступ к местоположению не предоставлен. Можно продолжить без него."),{enableHighAccuracy:false,timeout:12000,maximumAge:60000});}
$("#captureLocation")?.addEventListener("click",askLocationForForm);$("#myLocationBtn")?.addEventListener("click",askLocation);


/* QR Tags client: create, print, reopen and manage tags on this device. */
const QR_TAGS_KEY="topdim_qr_tags_v1";
let activeTagUrl="",activeTagManageToken="";
function readMyQrTags(){try{return JSON.parse(localStorage.getItem(QR_TAGS_KEY)||"[]").filter(x=>x&&x.id&&x.token);}catch{return[];}}
function saveMyQrTags(items){localStorage.setItem(QR_TAGS_KEY,JSON.stringify(items.slice(0,50)));}
function tagUrl(id){const u=new URL("/",location.origin);u.searchParams.set("tag",id);return u.href;}
function qrTagPayload(){return {title:$("#qrTagTitle").value.trim(),description:$("#qrTagDescription").value.trim(),return_message:$("#qrTagMessage").value.trim()};}
function refreshQrPreview(){const title=$("#qrTagTitle").value.trim()||"Твоя вещь";$("#qrPreviewTitle").textContent=title;$("#qrPreviewText").textContent=$("#qrTagDescription").value.trim()||"Отсканируй, чтобы открыть страницу возврата";$("#qrDescriptionCount").textContent=$("#qrTagDescription").value.length+" / 240";$("#qrMessageCount").textContent=$("#qrTagMessage").value.length+" / 240";}
function drawTagQr(url){if(!window.QRCode){$("#qrTagError").textContent="Генератор QR не загрузился. Обнови страницу.";return false;}$("#qrTagCanvas").innerHTML="";new QRCode($("#qrTagCanvas"),{text:url,width:178,height:178,colorDark:"#17251d",colorLight:"#ffffff",correctLevel:QRCode.CorrectLevel.H});return true;}
function renderMyQrTags(){const list=readMyQrTags(),root=$("#myQrTagsList");if(!root)return;if(!list.length){root.innerHTML='<p class="my-qr-empty">Пока нет сохранённых QR-кодов. Создай первую метку.</p>';return;}root.innerHTML=list.map(x=>'<article class="my-qr-tag"><div><b>'+safe(x.title||"Метка без названия")+'</b><small>Создана · '+safe(new Date(x.createdAt||Date.now()).toLocaleDateString("ru-RU"))+'</small></div><div class="my-qr-tag-actions"><button type="button" data-tag-open="'+safe(x.id)+'"><svg><use href="/icons.svg#external-link"/></svg> Открыть</button><button type="button" data-tag-edit="'+safe(x.id)+'"><svg><use href="/icons.svg#edit"/></svg> Изменить</button></div></article>').join("");}
function showCreatedTag(tag,token){activeTagUrl=tagUrl(tag.id);activeTagManageToken=token||"";drawTagQr(activeTagUrl);$("#qrTagResult").classList.remove("hidden");$("#qrTagResult").querySelector("b").textContent="QR-код готов к печати";$("#qrPreviewTitle").textContent=tag.title||"Твоя вещь";$("#qrPreviewText").textContent=tag.description||"Отсканируй, чтобы открыть страницу возврата";$("#downloadTagKey").disabled=!token;$("#downloadTagKey").innerHTML='<svg><use href="/icons.svg#key"></use></svg> '+(token?"Сохранить ключ управления":"Ключ сохранён ранее");}
$("#qrTagForm")?.addEventListener("submit",async e=>{e.preventDefault();const error=$("#qrTagError"),button=$("#qrTagSubmit"),id=$("#qrTagForm").dataset.editId;error.textContent="";button.disabled=true;button.textContent=id?"Сохраняем…":"Создаём QR…";try{const payload=qrTagPayload();const saved=readMyQrTags();let response;if(id){const own=saved.find(x=>x.id===id);if(!own)throw Error("Ключ управления не найден на этом устройстве.");response=await fetch("/api/qr-tags/"+encodeURIComponent(id),{method:"PUT",headers:{"Content-Type":"application/json","X-Manage-Token":own.token},body:JSON.stringify(payload)});}else{response=await fetch("/api/qr-tags",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});}const result=await response.json();if(!response.ok)throw Error(result.error||"Не удалось сохранить QR.");if(id){const next=saved.map(x=>x.id===id?{...x,title:result.tag.title,description:result.tag.description,returnMessage:result.tag.returnMessage}:x);saveMyQrTags(next);showCreatedTag(result.tag,next.find(x=>x.id===id)?.token||"");}else{const record={id:result.tag.id,title:result.tag.title,description:result.tag.description,returnMessage:result.tag.returnMessage,createdAt:result.tag.createdAt,token:result.manageToken};saveMyQrTags([record,...saved]);showCreatedTag(result.tag,result.manageToken);}renderMyQrTags();$("#qrTagForm").dataset.editId="";$("#qrFormTitle").textContent="Создать QR-метку";$("#qrTagSubmit").innerHTML='<svg><use href="/icons.svg#qr-code"></use></svg> Создать бесплатный QR';$("#qrTagCancelEdit").classList.add("hidden");toast(id?"Информация QR обновлена.":"QR-метка создана.");}catch(err){error.textContent=err.message||"Ошибка соединения.";}finally{button.disabled=false;if(!$("#qrTagForm").dataset.editId)button.innerHTML='<svg><use href="/icons.svg#qr-code"></use></svg> Создать бесплатный QR';else button.textContent="Сохранить изменения";}});
["qrTagTitle","qrTagDescription","qrTagMessage"].forEach(id=>$("#"+id)?.addEventListener("input",refreshQrPreview));
$("#qrTagCancelEdit")?.addEventListener("click",()=>{const f=$("#qrTagForm");f.reset();f.dataset.editId="";$("#qrFormTitle").textContent="Создать QR-метку";$("#qrTagSubmit").innerHTML='<svg><use href="/icons.svg#qr-code"></use></svg> Создать бесплатный QR';$("#qrTagCancelEdit").classList.add("hidden");$("#qrTagError").textContent="";refreshQrPreview();});
$("#myQrTagsList")?.addEventListener("click",e=>{const edit=e.target.closest("[data-tag-edit]"),open=e.target.closest("[data-tag-open]");if(edit){const x=readMyQrTags().find(v=>v.id===edit.dataset.tagEdit);if(!x)return;$("#qrTagTitle").value=x.title||"";$("#qrTagDescription").value=x.description||"";$("#qrTagMessage").value=x.returnMessage||"";const f=$("#qrTagForm");f.dataset.editId=x.id;$("#qrFormTitle").textContent="Изменить QR-метку";$("#qrTagSubmit").textContent="Сохранить изменения";$("#qrTagCancelEdit").classList.remove("hidden");$("#qrTagError").textContent="";refreshQrPreview();$("#qrTags").scrollIntoView({behavior:"smooth"});}else if(open){const x=readMyQrTags().find(v=>v.id===open.dataset.tagOpen);if(x){showCreatedTag(x,x.token);$("#qrTags").scrollIntoView({behavior:"smooth"});}}});
$("#downloadTagQr")?.addEventListener("click",()=>{const canvas=$("#qrTagCanvas canvas"),img=$("#qrTagCanvas img"),data=canvas?canvas.toDataURL("image/png"):img?.src;if(!data)return toast("QR ещё создаётся.");const a=document.createElement("a");a.href=data;a.download="topdim-tag-"+(new URL(activeTagUrl).searchParams.get("tag")||"qr")+".png";a.click();});

$("#printTagQr")?.addEventListener("click",()=>{if(!activeTagUrl)return toast("Сначала создай QR-код.");document.body.classList.add("printing-tag");const done=()=>{document.body.classList.remove("printing-tag");window.removeEventListener("afterprint",done);};window.addEventListener("afterprint",done);window.print();setTimeout(done,120000);});
$("#copyTagLink")?.addEventListener("click",async()=>{if(!activeTagUrl)return;try{await navigator.clipboard.writeText(activeTagUrl);toast("Ссылка скопирована.");}catch{toast("Не удалось скопировать ссылку.");}});
$("#downloadTagKey")?.addEventListener("click",()=>{if(!activeTagManageToken)return toast("Ключ уже сохранён на этом устройстве.");const text="TOPDIM QR TAG — PRIVATE MANAGEMENT KEY\nURL: "+activeTagUrl+"\nMANAGEMENT KEY: "+activeTagManageToken+"\n\nKeep this key private. Anyone with this key can edit or deactivate this QR tag.";const blob=new Blob([text],{type:"text/plain;charset=utf-8"}),u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u;a.download="topdim-qr-management-key.txt";a.click();URL.revokeObjectURL(u);toast("Файл с ключом подготовлен.");});

function decorateActionButtons(){
 const rules=[['#clearFilters,#emptyReset','refresh'],['#searchBtn','search'],['#openQrScanner','scan-qr'],['#myLocationBtn,#captureLocation','crosshair'],['#mapReset','map'],['#partnerBtn','handshake'],['#submitBtn','send'],['#stopScanner','camera-off']];
 rules.forEach(([selector,name])=>document.querySelectorAll(selector).forEach(btn=>{if(btn.querySelector("svg"))return;const svg=document.createElementNS("http://www.w3.org/2000/svg","svg"),use=document.createElementNS("http://www.w3.org/2000/svg","use");svg.setAttribute("aria-hidden","true");use.setAttribute("href","/icons.svg#"+name);svg.append(use);btn.prepend(svg);}));
}
async function openPublicTag(id){if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)){toast("Некорректная QR-метка.");return;}const root=$("#publicTagContent");root.innerHTML="<p>Загружаем информацию…</p>";openQrLayer("publicTagBackdrop");try{const r=await fetch("/api/qr-tags/"+encodeURIComponent(id));const data=await r.json();if(!r.ok)throw Error(data.error||"QR-метка недоступна.");const x=data.tag;$("#publicTagTitle").textContent=x.title||"Информация о вещи";let content="";if(x.title)content+='<div class="public-tag-content-title">НАЗВАНИЕ ВЕЩИ</div>';if(x.description)content+='<div class="public-tag-description">'+safe(x.description)+'</div>';if(x.returnMessage)content+='<div class="public-tag-content-title">СООБЩЕНИЕ ОТ ВЛАДЕЛЬЦА</div><div class="public-tag-message">'+safe(x.returnMessage)+'</div>';if(!content)content='<div class="public-tag-empty">Владелец пока не добавил информацию. Если ты нашёл эту вещь, сохрани QR-страницу и попробуй проверить позже.</div>';root.innerHTML=content;history.replaceState(null,"",tagUrl(id));}catch(err){root.innerHTML='<div class="public-tag-empty">'+safe(err.message||"Не удалось открыть QR-метку.")+'</div>';}}
document.querySelectorAll("[data-close-public-tag]").forEach(b=>b.addEventListener("click",()=>closeQrLayer("publicTagBackdrop")));
$("#publicTagBackdrop")?.addEventListener("click",e=>{if(e.target.id==="publicTagBackdrop")closeQrLayer("publicTagBackdrop");});
renderMyQrTags();refreshQrPreview();decorateActionButtons();
const directTag=new URLSearchParams(location.search).get("tag");if(directTag)openPublicTag(directTag);
